  render(){const ru=this.language.startsWith('ru'),readyHint=ru?'Отпустите для подтверждения':'Release to confirm',duration=(this.duration/1000).toLocaleString(ru?'ru':'en'),hint=this._ready?(this.compact&&ru?'Отпустите':readyHint):(ru?(this.compact?'Держать ':'Удерживайте ')+duration+' с':'Hold '+duration+' s');return html`<button type="button" class="${this._holding?'holding':''} ${this._ready?'ready':''}" ?disabled=${this.disabled} aria-label=${this.label} aria-describedby="hint" @pointerdown=${this.pointerDown} @pointermove=${this.pointerMove} @pointerup=${e=>this.release(e.pointerId)} @pointercancel=${this.cancel} @lostpointercapture=${this.cancel} @blur=${this.cancel} @keydown=${this.keyDown} @keyup=${this.keyUp} @contextmenu=${e=>e.preventDefault()} @click=${this.click}>${this.icon?icon(this.icon):''}<span class="copy"><span>${this.label}</span><span id="hint" class="hint">${hint}</span></span></button><div id="hold-feedback" class="feedback ${this._holding?'tracking':''} ${this._ready?'ready':''}" popover="manual" hidden style=${'--hold-duration:'+this.duration+'ms'} role="status" aria-live="polite" aria-atomic="true"><span class="feedback-title">${this.label}</span><div class="track" aria-hidden="true"><div class="progress"></div></div><span class="feedback-hint">${this._ready?readyHint:(ru?'Удерживайте '+duration+' с':'Hold '+duration+' s')}</span></div>`;}
