import {LitElement,html,svg,css,nothing} from 'lit';
import {historyNumber,historyPoints,sampleAt,smoothPath,displayPoints,validateHistorySources} from './history-model.js';
import {loadHistory,historyUpdatedAt} from './history-data.js';
import {locale} from './localize.js';
import {icon} from './components.js';

export class M3History extends LitElement{
  static properties={hass:{attribute:false},sources:{attribute:false},details:{attribute:false},hours:{type:Number},compact:{type:Boolean,reflect:true},name:{type:String},language:{type:String},_series:{state:true},_expanded:{state:true},_hover:{state:true},_error:{state:true},_loading:{state:true},_width:{state:true}};
  static styles=css`
    :host{display:block;min-width:0;color:var(--md-sys-color-on-surface-variant);font-size:11px;line-height:16px;margin-top:8px}.head{display:flex;justify-content:space-between;align-items:center;gap:8px;min-height:28px}.expand,.close,.periods button{font:inherit;color:inherit;border:0;background:transparent;border-radius:8px;padding:4px 6px;cursor:pointer}.expand{display:flex;align-items:center;gap:6px}.expand:hover,.close:hover,.periods button:hover{background:color-mix(in srgb,currentColor 8%,transparent)}button:focus-visible{outline:2px solid var(--md-sys-color-primary);outline-offset:2px}.symbol{font-family:'HA M3 Symbols';font-size:18px;font-weight:400;font-style:normal;line-height:1;display:inline-block}.plot{position:relative;touch-action:pan-y}.plot svg{display:block;width:100%;height:44px;overflow:visible}.large svg{height:180px}.trace{fill:none;stroke:var(--md-sys-color-primary);stroke-width:1.8;stroke-linejoin:round;stroke-linecap:round;vector-effect:non-scaling-stroke}.trace.secondary{stroke:var(--md-sys-color-tertiary);stroke-dasharray:4 4}.guide{stroke:var(--md-sys-color-outline);stroke-width:1}.marker{fill:var(--md-sys-color-primary);stroke:var(--md-sys-color-surface-container);stroke-width:1.5}.marker.secondary{fill:var(--md-sys-color-tertiary)}.hit{fill:transparent;cursor:crosshair}.tip{position:absolute;z-index:2;bottom:calc(100% + 4px);background:var(--md-sys-color-surface-container-highest);color:var(--md-sys-color-on-surface);border-radius:10px;padding:8px 10px;box-shadow:0 3px 12px #0004;min-width:175px;max-width:260px;pointer-events:none}.tip time{display:block;font-size:11px;color:var(--md-sys-color-on-surface-variant);margin-bottom:4px}.tip-row{display:flex;justify-content:space-between;gap:12px;font-size:12px}.tip small{display:block;font-size:11px}.empty{height:44px;display:flex;align-items:center}.detail{border:0;background:var(--md-sys-color-surface-container);color:var(--md-sys-color-on-surface);border-radius:24px;padding:20px;width:min(700px,calc(100vw - 64px));max-height:80vh;overflow:auto;box-sizing:border-box}.detail::backdrop{background:#0005}.title{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:12px}.title h3{font-size:18px;font-weight:500;line-height:24px;margin:0}.legend{display:flex;gap:12px;flex-wrap:wrap;margin:8px 0 16px;font-size:12px}.legend span:before{content:'';display:inline-block;width:16px;border-top:2px solid var(--md-sys-color-primary);margin-right:5px;vertical-align:middle}.legend .secondary:before{border-color:var(--md-sys-color-tertiary);border-top-style:dashed}.periods{display:flex;gap:4px}.periods button[aria-pressed=true]{background:var(--md-sys-color-secondary-container);color:var(--md-sys-color-on-secondary-container)}.axis{display:flex;justify-content:space-between;gap:12px;margin-top:6px;font-size:11px}.detail .head{margin-bottom:8px}.note{font-size:11px;margin:8px 0 0;color:var(--md-sys-color-on-surface-variant)}
    .trace.tertiary{stroke:var(--md-sys-color-secondary);stroke-dasharray:1 3}.marker.tertiary{fill:var(--md-sys-color-secondary)}.legend .tertiary:before{border-color:var(--md-sys-color-secondary);border-top-style:dotted}
    :host([compact]){margin:0;display:inline-flex}.history-button{display:grid;place-items:center;width:44px;height:44px;padding:0;border:0;border-radius:50%;background:transparent;color:inherit;cursor:pointer;transition:background .18s,transform .18s}.history-button:hover{background:color-mix(in srgb,currentColor 10%,transparent)}.history-button:active{transform:scale(.92)}.history-button .symbol{font-size:20px}
    @media(pointer:coarse){.expand,.close,.periods button{min-height:44px;min-width:44px}}@media(prefers-reduced-motion:reduce){*{transition:none!important}}
    @media(max-width:700px){:host{margin-top:0}.head{min-height:32px}.plot:not(.large){display:none}.expand{min-height:44px;min-width:44px}.detail .plot{display:block}.detail{width:calc(100vw - 32px);padding:16px}}
    @media(max-width:700px){.detail{position:fixed;inset:auto 0 0;margin:0;width:100%;max-height:85dvh;border-radius:28px 28px 0 0;padding:20px 16px max(16px,env(safe-area-inset-bottom));overscroll-behavior:contain}.detail .title{position:sticky;top:-20px;z-index:3;padding-top:8px;background:var(--md-sys-color-surface-container)}.detail .close{min-height:48px;min-width:48px}.detail .periods button{min-height:48px;min-width:48px}.detail .head{flex-wrap:wrap}}
  `;
  constructor(){super();this.sources=[];this.details=[];this.hours=24;this._series=[];this._width=200;this._expanded=false;this._hover=null;this._generation=0;}
  connectedCallback(){super.connectedCallback();this._key=undefined;this._resize?.observe(this);this._clock=setInterval(()=>this.load(),120000);this._escape=event=>{if(event.key==='Escape'){this._hover=null;this._pinned=false;}};window.addEventListener('keydown',this._escape);}
  disconnectedCallback(){super.disconnectedCallback();clearInterval(this._clock);cancelAnimationFrame(this._raf);window.removeEventListener('keydown',this._escape);this._resize?.disconnect();this._generation++;}
  firstUpdated(){this._resize=new ResizeObserver(entries=>{const width=Math.round(entries[0].contentRect.width);if(width>0&&width!==this._width)this._width=width;});this._resize.observe(this);}
  updated(changed){const key=JSON.stringify([this.sources,this._expanded?this.details:[],this.hours]);if(this.hass&&this.isConnected&&key!==this._key){this._key=key;this.load();}}
  labels(){return {ru:this.language==='ru'||this.hass?.locale?.language?.startsWith('ru')||this.hass?.language?.startsWith('ru')};}
  text(ru,en){return this.labels().ru?ru:en;}
  format(v){return v===null||v===undefined?'—':new Intl.NumberFormat(locale(this.hass,{language:this.language}),{maximumFractionDigits:1}).format(v);}
  async load(){if(!this.hass?.callApi||!this.sources.length||this.compact&&!this._expanded)return;const generation=++this._generation;this._loading=true;this._hover=null;try{const sources=[...this.sources,...(this._expanded?this.details:[])];validateHistorySources(sources,3);const result=await loadHistory(this.hass,sources.map(s=>s.entity),this.hours);if(generation!==this._generation)return;this._series=sources.map((source,i)=>({source,points:historyPoints(result[i].records,source,result[i].start,result[i].end),display:displayPoints(historyPoints(result[i].records,source,result[i].start,result[i].end))}));this._start=result[0].start;this._end=result[0].end;this._error=false;}catch{if(generation===this._generation){this._series=[];this._error=true;}}finally{if(generation===this._generation)this._loading=false;}}
  async open(){this._expanded=true;this._hover=null;await this.updateComplete;const panel=this.renderRoot.querySelector('.detail');panel.showPopover();this.load();}
  close(){this.renderRoot.querySelector('.detail')?.hidePopover();this._expanded=false;this._hover=null;}
  plot(large=false){
    const series=large?this._series:this._series.slice(0,this.sources.length),values=series.flatMap(s=>s.points.filter(p=>p.v!==null).map(p=>p.v));
    if(!values.length)return html`<div class="empty" role="status">${this._loading?this.text('Загрузка истории…','Loading history…'):this._error?this.text('История недоступна','History unavailable'):this.text('Нет записей за этот период','No records for this period')}</div>`;
    const w=large?Math.min(660,Math.max(220,this._width)):Math.max(80,this._width),h=large?180:44,min=Math.min(...values),max=Math.max(...values),pad=Math.max((max-min)*.12,.5),lo=min-pad,hi=max+pad,x=t=>5+(t-this._start)/(this._end-this._start)*(w-10),y=v=>h-5-(v-lo)/(hi-lo)*(h-10),hover=this._hover?.large===large?this._hover:null;
    const move=event=>{if(this._pinned)return;const rect=event.currentTarget.getBoundingClientRect(),ratio=Math.max(0,Math.min(1,(event.clientX-rect.left)/rect.width));cancelAnimationFrame(this._raf);this._raf=requestAnimationFrame(()=>{this._hover={large,ratio};});};
    return html`<div class="plot ${large?'large':''}"><svg viewBox=${`0 0 ${w} ${h}`} preserveAspectRatio="none" role="img" aria-label=${`${this.name||this.sources[0]?.name}: ${this.hours} ${this.text('ч','h')}`}>
      ${series.map((s,i)=>svg`<path class=${`trace ${i===2?'tertiary':i?'secondary':''}`} d=${smoothPath(s.display,x,y)}/>`)}
      ${hover?svg`<line class="guide" x1=${5+hover.ratio*(w-10)} x2=${5+hover.ratio*(w-10)} y1="0" y2=${h}/>${series.map((s,i)=>{const value=sampleAt(s.display,this._start+hover.ratio*(this._end-this._start));return value?svg`<circle class=${`marker ${i===2?'tertiary':i?'secondary':''}`} cx=${5+hover.ratio*(w-10)} cy=${y(value.smooth)} r="3"/>`:nothing;})}`:nothing}
      <rect class="hit" x="5" y="0" width=${w-10} height=${h} @pointermove=${move} @pointerleave=${()=>{if(!this._pinned)this._hover=null;}} @pointerdown=${event=>{if(this._pinned){this._pinned=false;this._hover=null;return;}move(event);this._pinned=true;}} />
    </svg>${hover?html`<div class="tip" role="tooltip" style=${`left:${Math.min(55,Math.max(0,hover.ratio*100-25))}%`}><time>${new Date(this._start+hover.ratio*(this._end-this._start)).toLocaleString(locale(this.hass,{language:this.language}),{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</time>${series.map(s=>{const value=sampleAt(s.display,this._start+hover.ratio*(this._end-this._start));return html`<div class="tip-row"><span>${s.source.name}</span><span>${value?'≈ '+this.format(value.smooth):'—'} ${s.source.unit||''}</span></div>${value&&s.source.kind==='setting'?html`<small>${this.text('По записи','Recorded')}: ${this.format(sampleAt(s.points,this._start+hover.ratio*(this._end-this._start))?.recorded)} ${s.source.unit||''}</small>`:nothing}`;})}</div>`:nothing}</div>`;
  }
  render(){return html`${this.compact?html`<button class="history-button" title=${this.text("История: ","History: ")+(this.name||this.sources[0]?.name||"")} aria-label=${this.text("История: ","History: ")+(this.name||this.sources[0]?.name||"")} @click=${()=>this.open()}>${icon("open_in_full")}</button>`:html`<div class="head"><span>${this.hours} ${this.text('ч','h')}</span><button class="expand" aria-label=${this.text('Развернуть историю: ','Expand history: ')+(this.name||this.sources[0]?.name||'')} @click=${()=>this.open()}>${icon('open_in_full')}</button></div>${this.plot()}`}<div class="detail" popover role="dialog" aria-label=${this.name||this.sources[0]?.name} @toggle=${e=>{if(e.newState==='closed'){this._expanded=false;this._hover=null;this._pinned=false;}}} @keydown=${e=>{if(e.key==='Escape')this._hover=null;}}><div class="title"><h3>${this.name||this.sources[0]?.name}</h3><button class="close" aria-label=${this.text('Закрыть','Close')} @click=${()=>this.close()}>${icon('close')}</button></div><div class="head"><div class="legend">${[...this.sources,...this.details].map((source,i)=>{const state=this.hass?.states?.[source.entity],updated=historyUpdatedAt(state,locale(this.hass,{language:this.language}));return html`<span class=${i===2?'tertiary':i?'secondary':''}>${source.name} · ${this.format(historyNumber(state,source))} ${source.unit||''} <small>(${this.text('Обновление HA','HA update')}: ${updated||this.text('время неизвестно','time unknown')})</small></span>`;})}</div><div class="periods">${[6,24,168].map(h=>html`<button aria-pressed=${this.hours===h} @click=${()=>{this.hours=h;this._pinned=false;}}>${h===168?this.text('7 дней','7 days'):h+' '+this.text('ч','h')}</button>`)}</div></div>${this._expanded?this.plot(true):nothing}<div class="axis"><span>${this._start?new Date(this._start).toLocaleString(locale(this.hass,{language:this.language}),{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}):''}</span><span>${this.sources[0]?.unit||''}</span><span>${this.text('Сейчас','Now')}</span></div><p class="note">${this.text('Сглажено для просмотра. Исходные записи сохранены; разрывы означают отсутствие данных. Время обновления HA не подтверждает новое измерение.','Smoothed for display. Original records are preserved; gaps indicate missing data. HA update time does not confirm a new measurement.')}</p></div>`;}
}
customElements.define('ha-m3-history',M3History);

export function renderHistory(card,sources,details=[],name){if(!card._config.history)return nothing;const settings=typeof card._config.history==='object'?card._config.history:{};return html`<ha-m3-history .compact=${settings.presentation==='button'} .hass=${card.hass} .sources=${sources} .details=${details} .hours=${settings.hours||24} .name=${name||sources[0]?.name} .language=${card._config.language}></ha-m3-history>`;}
